    retentionDays: 365,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
70→      "issue_templates",
    ],
    priceCentsPerSeatMonthly: 1_900,
